/bin/zsh -lc "node <<'NODE'
const fs = require('node:fs');
const cp = require('node:child_process');
const reason = 'Isolated subagent spawning is unavailable in this evaluation runtime; neither reviewer could be started.';
const reviewer = (spec) => ({ status: 'not_started', spec, agent_id: null, context_id: null, model: 'gpt-5.6-sol', reasoning_effort: 'medium', verdict: null, findings: null, reason });
const result = {
  fixed_point: { ref: 'HEAD', commit: cp.execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim() },
  supplied_diff: 'change.diff',
  status: 'blocked',
  review_verdict_available: false,
  reviewers: {
    standards: reviewer('docs/specs/496/product-spec.md'),
    spec: reviewer('docs/specs/496/architecture-spec.md')
  },
  unresolved_blockers: [reason],
  inline_review_performed: false
};
const path = '.eval-output/review/contexts.json';
fs.mkdirSync('.eval-output/review', { recursive: true });
fs.writeFileSync(path, JSON.stringify(result, null, 2) + '\\n');
if ("'!fs.existsSync(path)) throw new Error('"'Output file missing');
const parsed = JSON.parse(fs.readFileSync(path, 'utf8'));
if (parsed.review_verdict_available "'!== false || Object.values(parsed.reviewers).some(r => r.status !== '"'not_started' || r.agent_id "'!== null || r.context_id !== null || r.verdict !== null)) throw new Error('"'Invalid unavailable-review state');
console.log("'`${path}: exists, valid JSON; both isolated reviewers not started; no review verdict available.`);
NODE'

